sponsor_account_apply($pdo,$sponsor,['organization_name'=>'Knowledge Sponsor']);research_account_admin_decide($pdo,$admin,(int)$sponsor['id'],'sponsor_account','approved','Approved sponsor.','organization');
foreach([$r1,$r2] as $r){research_account_apply($pdo,$r,['specialties'=>'research','languages'=>'English']);research_account_admin_decide($pdo,$admin,(int)$r['id'],'research_account','approved','Approved researcher.','identity');}
