$campaign=sponsored_research_campaign_create($pdo,$sponsor,['account_id'=>$accountPublic,'title'=>'Knowledge Release Campaign','brief'=>'Build governed Sponsored Research Knowledge.','objective'=>'Validate explicit promotion and immutable releases.','questions'=>['What does the evidence support?'],'access_mode'=>'public','budget'=>'1000.00','eligibility'=>['min_verification'=>'identity'],'disclosures'=>['sponsorship_disclosure_required'=>false,'conflict_disclosure_required'=>false,'nda_required'=>false],'submission_deadline'=>'2030-12-31 23:59:00']);
$campaign=sponsored_research_campaign_set_status($pdo,$sponsor,(string)$campaign['public_id'],'open');sponsored_research_campaign_terms_publish($pdo,$sponsor,(string)$campaign['public_id'],'Accepted work may be explicitly promoted into the sponsor Knowledge Base. Training rights remain separate.','Knowledge terms.');
