$submit=function(array $researcher,string $suffix)use($pdo,$campaign,$pub,$run):array{
 sponsored_research_campaign_join($pdo,$researcher,(string)$campaign['public_id'],['accept_terms'=>true]);
 $sourcePublic=$pub('source'.$suffix);$url='https://'.$run.'.example.test/'.$suffix;$pdo->prepare("INSERT INTO sources(public_id,source_type,canonical_url,canonical_url_hash,domain,title,status) VALUES(?,'article',?,?,?,?, 'current')")->execute([$sourcePublic,$url,hash('sha256',$url),$run.'.example.test','Knowledge Source '.$suffix]);$sourceId=(int)$pdo->lastInsertId();
 $txt='Knowledge evidence '.$suffix.' '.$run;$pdo->prepare('INSERT INTO source_versions(source_id,version_number,final_url,title,extracted_text,content_hash,target_content_hash) VALUES(?,1,?,?,?,?,?)')->execute([$sourceId,$url,'Knowledge Source '.$suffix,$txt,hash('sha256',$txt),hash('sha256','target '.$suffix.$run)]);$sv=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE sources SET current_version_id=? WHERE id=?')->execute([$sv,$sourceId]);
 $pdo->prepare("INSERT INTO source_rights(source_id,rights_class,retrieval_allowed,excerpt_storage_allowed,model_context_allowed,training_allowed,commercial_training_allowed,license_code,rights_holder,review_status,reviewed_by_user_id,reviewed_at) VALUES(?,'licensed',1,1,1,0,0,'SPONSORED-KB','Publisher','reviewed',?,NOW())")->execute([$sourceId,(int)$researcher['id']]);
 $pdo->prepare("INSERT INTO captures(public_id,source_id,source_version_id,user_id,capture_type,selected_text) VALUES(?,?,?,?, 'text',?)")->execute([$pub('cap'.$suffix),$sourceId,$sv,(int)$researcher['id'],'Selected evidence '.$suffix]);$cap=(int)$pdo->lastInsertId();
 $ann=$pub('ann'.$suffix);$pdo->prepare("INSERT INTO annotations(public_id,user_id,source_id,source_version_id,capture_id,text_commentary,visibility,status) VALUES(?,?,?,?,?,?,'private','draft')")->execute([$ann,(int)$researcher['id'],$sourceId,$sv,$cap,'Knowledge analysis '.$suffix.' '.$run]);
 $draft=sponsored_research_submission_draft($pdo,$researcher,(string)$campaign['public_id'],['title'=>'Knowledge submission '.$suffix,'summary'=>'Accepted knowledge candidate '.$suffix,'methodology'=>'Source review.','limitations'=>'Test scope.']);
 $sub=sponsored_research_submission_submit($pdo,$researcher,(string)$draft['public_id'],[['type'=>'annotation','public_id'=>$ann],['type'=>'source','public_id'=>$sourcePublic]]);
 return ['submission'=>$sub,'annotation'=>$ann,'source'=>$sourcePublic];
};
$a=$submit($r1,'one');sponsored_research_compensation_reserve($pdo,$sponsor,(string)$a['submission']['public_id'],30000);$case1=sponsored_research_review_open($pdo,$sponsor,(string)$a['submission']['public_id'],[]);$case1=sponsored_research_review_decide($pdo,$sponsor,(string)$case1['public_id'],'accepted','Accepted for Knowledge.');
$b=$submit($r2,'two');sponsored_research_compensation_reserve($pdo,$sponsor,(string)$b['submission']['public_id'],30000);$case2=sponsored_research_review_open($pdo,$sponsor,(string)$b['submission']['public_id'],[]);$case2=sponsored_research_review_decide($pdo,$sponsor,(string)$case2['public_id'],'accepted','Accepted correction candidate.');

$kb=sponsored_research_knowledge_base_create($pdo,$sponsor,(string)$campaign['public_id'],['name'=>'Campaign Canonical Knowledge']);p80s7($kb['status']==='draft'&&(int)$kb['current_release_number']===0,'Knowledge Base begins as a draft with no implicit promotion.');
$assets=sponsored_research_knowledge_promotable_assets($pdo,$sponsor,(string)$campaign['public_id']);$annAsset1=null;$srcAsset1=null;$annAsset2=null;foreach($assets as $x){if($x['asset_public_id']===$a['annotation'])$annAsset1=$x;if($x['asset_public_id']===$b['annotation'])$annAsset2=$x;}
$q=$pdo->prepare("SELECT a.* FROM sponsored_research_submission_assets a JOIN sponsored_research_submission_versions sv ON sv.id=a.submission_version_id JOIN sponsored_research_submissions s ON s.id=sv.submission_id WHERE s.public_id=? AND a.asset_type='source' LIMIT 1");$q->execute([(string)$a['submission']['public_id']]);$srcAsset1=$q->fetch();
p80s7($annAsset1!==null&&$annAsset2!==null,'Only accepted submission assets are exposed for explicit Knowledge promotion.');
$blockedSource=false;try{sponsored_research_knowledge_promote($pdo,$sponsor,(string)$kb['public_id'],(string)$srcAsset1['public_id']);}catch(RuntimeException $e){$blockedSource=true;}p80s7($blockedSource,'Sources remain evidence lineage and cannot become standalone authored Knowledge items.');

$item1=sponsored_research_knowledge_promote($pdo,$sponsor,(string)$kb['public_id'],(string)$annAsset1['public_id']);p80s7($item1['state']==='active'&&(int)$item1['future_use_allowed']===1,'Sponsor explicitly promotes accepted researcher work into an active Knowledge item.');
$q=$pdo->prepare("SELECT COUNT(*) FROM data_provenance_edges WHERE from_type='sponsored_submission_asset' AND from_public_id=? AND relationship='promoted_to' AND to_type='sponsored_knowledge_item' AND to_public_id=?");$q->execute([(string)$annAsset1['public_id'],(string)$item1['public_id']]);p80s7((int)$q->fetchColumn()===1,'Knowledge promotion preserves exact submission-asset provenance.');

$release1=sponsored_research_knowledge_release_create($pdo,$sponsor,(string)$kb['public_id'],'Initial governed release.');p80s7((int)$release1['release_number']===1&&strlen((string)$release1['manifest_hash'])===64,'Release 1 freezes an immutable manifest and hash.');
