$manifest1=(string)$release1['manifest_json'];

$q=$pdo->prepare("UPDATE source_rights sr JOIN sources s ON s.id=sr.source_id SET sr.retrieval_allowed=0 WHERE s.public_id=?");$q->execute([$a['source']]);$status=sponsored_research_knowledge_release_current_use_status($pdo,(string)$release1['public_id']);p80s7($status['usable']===false&&in_array('source_rights_block_future_use',$status['reasons'],true),'Later Source-rights revocation blocks future use of the old release without rewriting it.');
$q=$pdo->prepare("UPDATE source_rights sr JOIN sources s ON s.id=sr.source_id SET sr.retrieval_allowed=1,license_code='SPONSORED-KB-V2' WHERE s.public_id=?");$q->execute([$a['source']]);$status=sponsored_research_knowledge_release_current_use_status($pdo,(string)$release1['public_id']);p80s7($status['usable']===false&&in_array('source_rights_changed_since_release',$status['reasons'],true),'Rights/license drift invalidates the old release until a new release captures current rights.');
$release2=sponsored_research_knowledge_release_create($pdo,$sponsor,(string)$kb['public_id'],'Rights-refreshed release.');p80s7(sponsored_research_knowledge_release_current_use_status($pdo,(string)$release2['public_id'])['usable']===true,'A new immutable release captures the current Source-rights state.');

$item2=sponsored_research_knowledge_promote($pdo,$sponsor,(string)$kb['public_id'],(string)$annAsset2['public_id'],(string)$item1['public_id']);$old=sponsored_research_knowledge_item_get($pdo,(string)$item1['public_id']);p80s7($old['state']==='corrected'&&(int)$old['future_use_allowed']===0&&$item2['state']==='active','Correction creates a replacement item and marks the prior item corrected instead of editing history.');
