$q=$pdo->prepare("SELECT COUNT(*) FROM sponsored_research_knowledge_events WHERE knowledge_base_id=? AND event_type IN ('knowledge_item_promoted','knowledge_item_replacement_promoted','knowledge_item_corrected','knowledge_item_rights_revoked','knowledge_release_created')");$q->execute([(int)$kb['id']]);p80s7((int)$q->fetchColumn()>=7,'Knowledge governance events preserve promotion, correction, release and revocation history.');

